import type { D1AuthoredBank } from '../corpus'

export const PESISIR_UTARA_D_R4: D1AuthoredBank = {
  universeId: 'pesisir-utara',
  rubricId: 'D-R4',
  STRONG: [
    { chapters: [
      { chapterNumber: 6, title: 'Karung Diangkat Pagi', paragraphs: ['Pagi pertama musim garam, Sari mengangkat karung dari tumpukan dan merasakan bahunya menahan beban yang tidak seragam. Ia tidak memiliki alat untuk memastikan. Kuli bongkar tertawa ketika ia menanyakannya dan berkata tangan bukan timbangan. Sari mencatat hari kejadian pada tepi halaman muatan tanpa menyertakan angka berat.'] },
      { chapterNumber: 14, title: 'Bertanya di Loket', paragraphs: ['Sari mendatangi loket izin dan menanyakan mengapa berat karung garam pada berkas berbeda dengan hasil timbang. Petugas menjawab bahwa selisih kecil wajar karena udara lembap. Sari pulang membawa jawaban itu tanpa kertas apa pun. Ia percaya soal tersebut dapat diselesaikan dengan bertanya baik-baik kepada orang yang duduk di balik jendela kayu.'] },
      { chapterNumber: 15, title: 'Menimbang Ulang Sendiri', paragraphs: ['Alih-alih bertanya lagi, Sari membawa dua karung ke bak penimbang saat halaman sepi dan mencatat beratnya sendiri di buku kecil. Pak Uweng menutup pintu gudang agar tidak terlihat dari jalan. Selisihnya tujuh kilogram, jauh melewati alasan udara lembap. Untuk pertama kalinya ia memegang angka, bukan penjelasan lisan.'] },
      { chapterNumber: 16, title: 'Menyalin Berkas Kapal', paragraphs: ['Sari naik ke ruang nakhoda dan menyalin berkas muatan versi kapal, dokumen yang tidak pernah singgah di loket izin. Nakhoda membiarkannya menyalin sambil merokok di dekat tangga besi. Angka pada salinan itu cocok dengan timbangannya sendiri, sehingga selisih tujuh kilogram kini punya dua sumber yang saling menguatkan.'] },
      { chapterNumber: 32, title: 'Membaca di Sidang', paragraphs: ['Di sidang dermaga Sari membacakan tiga angka berdampingan: berkas loket, timbangan sendiri, salinan kapal. Regent Damar tidak lagi menyebut udara lembap sebab kalimat itu sudah tercatat sebagai jawaban resmi bulan lalu. Bu Hasnah menangis pelan di bangku belakang. Persoalan berat karung berpindah dari mulut ke ruang yang punya notulen.'] },
      { chapterNumber: 41, title: 'Notulen Diminta Salinan', paragraphs: ['Sari meminta salinan notulen sidang dermaga dan menerima lembar berstempel setelah menunggu enam hari. Ia membandingkan isinya dengan catatan tangannya sendiri dan menemukan satu angka tertukar. Koreksi diajukan tertulis pada hari yang sama. Petugas notulen memperbaikinya dan membubuhkan paraf di sisi kiri lembar tersebut.'] },
      { chapterNumber: 42, title: 'Timbangan Ditera Ulang', paragraphs: ['Bak penimbang gudang ditera ulang oleh petugas dari kota atas permintaan yang diajukan Pak Uweng. Hasilnya menunjukkan pergeseran empat kilogram pada beban penuh. Angka lama pada berkas Sari kini memiliki penjelasan teknis yang tidak berasal dari mulut siapa pun. Berita acara tera itu ia lampirkan pada bundel perkaranya.'] },
      { chapterNumber: 43, title: 'Nakhoda Dipindah Jalur', paragraphs: ['Nakhoda yang dulu membiarkan Sari menyalin berkas dipindahkan ke jalur timur tanpa pemberitahuan. Sari menyusul ke pelabuhan singgah dan meminta keterangan tertulis sebelum kapal berangkat. Lelaki itu menuliskannya di balik daftar awak. Kertas tersebut menjadi keterangan pertama yang bertanda tangan nakhoda, bukan sekadar salinan angka.'] },
      { chapterNumber: 44, title: 'Berkas Loket Hilang', paragraphs: ['Berkas loket bulan pertama dinyatakan hilang ketika pemeriksa memintanya. Sari mengganti kehilangan itu dengan salinan kapal, berita acara tera, dan notulen terkoreksi yang saling menunjuk tanggal sama. Kehilangan yang seharusnya menghentikan perkara justru memperlihatkan bahwa tiga sumber di luar loket sudah berdiri sendiri.'] },
      { chapterNumber: 45, title: 'Hasnah Memberi Keterangan', paragraphs: ['Bu Hasnah memberikan keterangan tertulis tentang siapa yang memerintahkan penulisan berat pada berkas gudang. Ia menyebut satu nama yang belum pernah muncul dalam bundel Sari. Keterangan itu ditandatangani di hadapan dua saksi kuli bongkar. Perkara berat karung memperoleh pelaku, bukan sekadar selisih angka.'] },
      { chapterNumber: 46, title: 'Nama Baru Ditelusuri', paragraphs: ['Nama tersebut ternyata milik juru tulis lama yang kini bekerja di kantor karcis feri. Sari mendatanginya pada jam istirahat dan bertanya tanpa membawa berkas apa pun. Lelaki itu mengakui menulis atas perintah lisan. Ia bersedia mengulangi pengakuan tersebut bila dipanggil resmi oleh pemeriksa pusat.'] },
      { chapterNumber: 47, title: 'Damar Menawarkan Selesai', paragraphs: ['Regent Damar mengundang Sari ke serambi dan menawarkan penyelesaian berupa pengembalian selisih tanpa pemeriksaan lanjutan. Ia menyebut angka yang lebih besar daripada kerugian sebenarnya. Sari menanyakan apakah tawaran itu akan dituliskan. Lelaki tersebut menutup percakapan dan tidak mengulanginya pada kesempatan mana pun.'] },
      { chapterNumber: 48, title: 'Bundel Diserahkan Pusat', paragraphs: ['Bundel perkara dikirim menuju kantor pusat pelabuhan dengan daftar isi bernomor serta tanda terima rangkap dua. Sari menyimpan salinan penerimaan di dalam kaleng yang dahulu menampung pecahan cap. Latif menemani sampai geladak feri. Sejak pengiriman itu, kelanjutan perkara tidak lagi bergantung pada kehadiran Sari sendiri.'] },
      { chapterNumber: 49, title: 'Menunggu Bersama Hasnah', paragraphs: ['Selama menunggu panggilan, Sari duduk di gudang garam bersama Bu Hasnah dan mengakui bahwa selama ini ia memakai perempuan itu sebagai perisai. Bu Hasnah menjawab bahwa ia mengetahuinya sejak berkas pertama. Keduanya menghitung karung sampai petang. Rasa bersalah yang lama disimpan akhirnya diucapkan dan diterima.'] },
      { chapterNumber: 50, title: 'Timbangan Baru Dipasang', paragraphs: ['Timbangan baru dipasang di gudang atas keputusan pemeriksa, dan juru tulis lama dipindahkan dari jalur garam. Sari kehilangan wewenang tanda tangan selama satu musim karena kelalaian menyimpan bukti. Setiap pagi ia masih hadir untuk menyaksikan penimbangan pertama dilakukan. Bu Hasnah menandatangani berkas dengan namanya sendiri.'] },
    ], justification: 'Each confrontation changes tactic, venue, and information: asking, self-weighing, copying the ship record, a minuted hearing, then a runway that adds recalibration, a named perpetrator, a refused settlement, and an aftermath where Sari pays and the store changes hands.' },
    { chapters: [
      { chapterNumber: 6, title: 'Daftar Ditempel Gudang', paragraphs: ['Daftar penanggung jawab bongkaran ditempel di dinding gudang garam dengan nama Bu Hasnah pada baris paling atas. Perempuan itu membacanya sambil membetulkan ikatan rambutnya lalu meneruskan pekerjaan. Sari berdiri agak jauh dan menghitung berapa bongkaran yang ditanggungkan pada satu orang. Angkanya sebelas untuk musim berjalan.'] },
      { chapterNumber: 14, title: 'Memohon Kepada Damar', paragraphs: ['Sari menemui Regent Damar di serambi kantor dan meminta agar nama Bu Hasnah dikeluarkan dari daftar penanggung jawab. Lelaki itu mendengarkan dengan sabar lalu menjanjikan akan mempertimbangkan. Tidak ada yang dituliskan. Sari pergi dengan perasaan telah diperlakukan sopan, meski tidak ada bagian daftar yang benar-benar berubah.'] },
      { chapterNumber: 15, title: 'Menawar Lewat Pengurus', paragraphs: ['Sari berganti jalan dan meminta Bu Hasnah sendiri mengajukan surat pengunduran dari daftar. Perempuan itu bersedia bila Sari bersedia menjadi saksi tertulis. Keduanya menyusun surat di gudang. Permintaan yang tadinya berupa iba kini berbentuk dokumen bernama, dan risikonya berpindah sebagian ke pundak Sari sendiri.'] },
      { chapterNumber: 16, title: 'Menempuh Jalur Pusat', paragraphs: ['Surat itu tidak diteruskan kantor izin, maka Sari menitipkannya kepada awak feri untuk diserahkan ke kantor pelabuhan pusat. Latif mengantar sampai tangga kapal. Untuk pertama kalinya persoalan daftar keluar dari Tanjung Rembang, dan Regent Damar kehilangan kemampuan menahan kertas dengan cara mendiamkannya.'] },
      { chapterNumber: 32, title: 'Menjawab Panggilan Pusat', paragraphs: ['Panggilan dari pusat tiba, dan Sari menjawabnya dengan membawa Bu Hasnah sekaligus salinan surat titipan. Regent Damar hadir sebagai pihak yang diminta menjelaskan, bukan pihak yang memutuskan. Kesabaran serambi kantor yang dulu terasa ramah kini berubah menjadi keterangan yang harus dipertanggungjawabkan di meja lain.'] },
      { chapterNumber: 41, title: 'Daftar Dipecah Tiga', paragraphs: ['Kantor pusat memerintahkan daftar penanggung jawab dipecah menjadi tiga nama per musim agar beban tidak menumpuk. Sari mengusulkan pembagiannya berdasarkan jenis muatan, bukan berdasarkan siapa yang paling mudah ditegur. Usulan itu diterima sebagian. Bu Hasnah kini hanya menanggung bongkaran garam, bukan seluruh gudang.'] },
      { chapterNumber: 42, title: 'Surat Titipan Dicari', paragraphs: ['Pemeriksa menanyakan surat yang dahulu dititipkan lewat awak feri, dan arsip pusat tidak menemukannya pada bundel manapun. Sari menyerahkan tanda terima yang disimpan Latif di dalam kotak karcis. Nomor pada tanda terima itu cocok dengan buku ekspedisi kapal. Surat tersebut ditemukan terselip di berkas jalur timur.'] },
      { chapterNumber: 43, title: 'Damar Kehilangan Wewenang', paragraphs: ['Wewenang menahan berkas dicabut dari kantor izin Tanjung Rembang dan dipindahkan ke pelabuhan singgah. Regent Damar tetap menduduki ruangannya tetapi tidak lagi memegang stempel penahanan. Ia mulai mengirim pesan lisan melalui kuli bongkar. Sari menolak menerima pesan yang tidak disampaikan langsung kepadanya.'] },
      { chapterNumber: 44, title: 'Hasnah Dipanggil Sendiri', paragraphs: ['Bu Hasnah dipanggil menghadap tanpa Sari, dan ia menjawab seluruh pertanyaan dengan berkas yang ia siapkan sendiri sejak surat pengunduran disusun. Pemeriksa mencatat bahwa keterangannya konsisten dengan buku muatan. Ketergantungan yang dahulu melekat pada Sari sudah tidak diperlukan lagi di dalam ruangan pemeriksaan itu.'] },
      { chapterNumber: 45, title: 'Saksi Tertulis Diuji', paragraphs: ['Keterangan saksi tertulis Sari diuji dengan pertanyaan silang selama hampir dua jam. Satu tanggal yang ia tulis dari ingatan terbukti meleset tiga hari. Ia mengakuinya tanpa mencoba membetulkan cerita. Pemeriksa menandai bagian itu sebagai lemah dan meneruskan sisa keterangannya sebagai bahan.'] },
      { chapterNumber: 46, title: 'Latif Menolak Mengantar', paragraphs: ['Latif menolak mengantar berkas berikutnya karena namanya mulai disebut di pos jaga sebagai kurir perkara. Sari tidak memaksanya dan mencari jalur pengiriman lain melalui pedagang ikan asin. Ongkosnya tiga kali lipat. Ia membayarnya dari upah dua pekan tanpa memberi tahu adiknya.'] },
      { chapterNumber: 47, title: 'Serambi Kantor Dikosongkan', paragraphs: ['Serambi tempat Sari dahulu memohon dikosongkan dan kursinya diangkut ke gudang belakang. Regent Damar menerima tamu di ruang dalam dengan pintu tertutup. Sari melewatinya setiap pagi dan tidak pernah lagi diundang masuk. Ia berhenti memperlambat langkah ketika melintasi bangunan tersebut.'] },
      { chapterNumber: 48, title: 'Keputusan Dibacakan Terbuka', paragraphs: ['Keputusan pusat dibacakan di halaman pelabuhan agar seluruh kuli bongkar dapat mendengarnya. Nama Bu Hasnah dicabut dari daftar penanggung jawab bongkaran lama. Regent Damar diminta memberikan penjelasan tertulis dalam tiga puluh hari. Sari menyimak dari ujung kerumunan dan tidak diminta memberi keterangan.'] },
      { chapterNumber: 49, title: 'Latif Diajak Bicara', paragraphs: ['Sari mendatangi Latif di pos feri dan mengakui bahwa ia telah memakai adiknya sebagai kurir tanpa menanyakan risikonya. Latif menjawab bahwa ia bersedia sejak awal, hanya ingin ditanya. Keduanya duduk memandangi kapal terakhir. Sari berjanji tidak akan mengirim apa pun tanpa bertanya lebih dahulu.'] },
      { chapterNumber: 50, title: 'Musim Baru Tanpa Perisai', paragraphs: ['Musim berikutnya dimulai dengan tiga nama pada daftar penanggung jawab dan tanda tangan Sari di antaranya. Ongkos kiriman berkas masih ia bayar sendiri sampai kas pelabuhan menggantinya delapan bulan kemudian. Regent Damar masih menduduki kantornya. Bu Hasnah menimbang karung pertama tanpa menoleh kepada siapa pun.'] },
    ], justification: 'The same demand escalates through four different routes and power positions, then the runway strips the antagonist of his stamp, tests her written statement to a proven error, costs her Latif as courier, and closes with a shared list she signs and a courier debt she repays.' },
    { chapters: [
      { chapterNumber: 6, title: 'Latif Mulai Bekerja', paragraphs: ['Latif diterima sebagai awak feri malam dan pulang membawa upah pertama dalam amplop cokelat kecil. Ia meletakkannya di meja dapur dengan bangga. Sari menghitungnya lalu menanyakan berapa jam ia bekerja untuk jumlah tersebut. Adiknya tidak dapat menjawab karena tidak pernah menghitung jamnya.'] },
      { chapterNumber: 14, title: 'Menegur Adik Malam', paragraphs: ['Sari menegur Latif di dapur karena membawa peti tanpa berkas ke feri malam. Adiknya membela diri dengan mengatakan semua awak melakukannya. Percakapan berhenti ketika lampu dapur padam. Tidak ada kesepakatan, hanya dua orang yang tidur dengan punggung saling membelakangi di kamar yang sama.'] },
      { chapterNumber: 15, title: 'Ikut Berlayar Sekali', paragraphs: ['Sari meminta izin ikut satu penyeberangan malam dan melihat sendiri bagaimana peti tanpa berkas dinaikkan lewat pintu belakang. Ia tidak menegur siapa pun di atas kapal. Sepulangnya, ia menuliskan urutan bongkar itu di buku kecil, dan pertengkaran dapur berubah menjadi pengetahuan yang dapat diuji.'] },
      { chapterNumber: 16, title: 'Menunjukkan Buku Kecil', paragraphs: ['Sari membuka buku kecil di hadapan Latif dan menunjuk baris waktu ketika petinya sendiri diangkat. Adiknya terdiam lama, lalu menyebut nama orang yang menyuruhnya. Nama itu belum pernah muncul di rumah mereka. Perselisihan keluarga berubah menjadi keterangan yang menunjuk keluar, bukan saling menyalahkan.'] },
      { chapterNumber: 32, title: 'Berdiri Bersama Adik', paragraphs: ['Ketika Latif dipanggil menghadap, Sari berdiri di sampingnya dan menyerahkan buku kecil sebagai bahan pemeriksaan. Adiknya menyebut nama itu sekali lagi di depan petugas. Keduanya kehilangan giliran kerja pekan itu, tetapi hubungan yang dulu putus di dapur gelap sekarang menanggung akibat bersama-sama.'] },
      { chapterNumber: 41, title: 'Nama Itu Dipanggil', paragraphs: ['Orang yang disebut Latif dipanggil menghadap dan datang membawa dua pengacara dari kota. Ia menyangkal pernah memberi perintah kepada awak feri manapun. Buku kecil Sari dibacakan bagian demi bagian. Sidang ditunda karena keterangan awak lain belum dikumpulkan seluruhnya. Dua awak yang dipanggil pada hari itu tidak hadir tanpa surat keterangan.'] },
      { chapterNumber: 42, title: 'Awak Lain Ditemui', paragraphs: ['Dalam rentang tiga malam, Sari dan Latif mengunjungi rumah empat awak feri satu per satu. Dua bersedia memberi keterangan, satu menolak, satu meminta waktu. Latif yang berbicara lebih dulu di setiap rumah karena mereka mengenalnya. Sari hanya mencatat tanpa memotong pembicaraan.'] },
      { chapterNumber: 43, title: 'Rumah Mereka Dilempari', paragraphs: ['Malam setelah keterangan kedua diserahkan, atap rumah mereka dilempari batu dan genting pecah di tiga tempat. Tidak ada yang terluka. Latif ingin membalas dan Sari menahannya dengan memegang lengannya sampai pagi. Mereka memperbaiki genting berdua tanpa melaporkan kejadian itu kepada siapa pun.'] },
      { chapterNumber: 44, title: 'Buku Kecil Disita', paragraphs: ['Buku kecil itu disita sebagai barang bukti dan Sari kehilangan satu-satunya catatan urutan bongkar yang ia miliki. Ia menuliskan ulang dari ingatan dan menandai bagian yang tidak ia yakini. Latif membantu mengisi jam-jam yang tidak ia saksikan. Versi kedua itu lebih pendek tetapi lebih jujur.'] },
      { chapterNumber: 45, title: 'Latif Diskors Sebulan', paragraphs: ['Perusahaan feri menskors Latif selama sebulan dengan alasan kelalaian tugas pada penyeberangan malam. Tanggal kelalaian itu adalah malam ketika Sari ikut berlayar. Latif tidak membantah dan menerima suratnya. Ia bekerja mengangkut peti ikan asin di pasar selama masa skors tersebut.'] },
      { chapterNumber: 46, title: 'Awak Keempat Bicara', paragraphs: ['Awak yang meminta waktu akhirnya datang sendiri ke rumah mereka membawa daftar upah yang tidak pernah ia terima selama tujuh pelayaran. Ia menyerahkannya kepada Latif, bukan kepada Sari. Daftar itu memuat nama yang sama dengan sebutan adiknya dahulu. Perkara memperoleh angka, bukan hanya kesaksian.'] },
      { chapterNumber: 47, title: 'Tawaran Pekerjaan Kota', paragraphs: ['Latif ditawari pekerjaan tetap di pelabuhan kota dengan syarat mencabut keterangannya. Tanpa ditanya, Latif mengabarkan tawaran tersebut kepada Sari malam itu juga. Keduanya menghitung upah yang hilang bila tawaran itu ditolak. Latif menolaknya keesokan pagi dan tetap mengangkut peti di pasar.'] },
      { chapterNumber: 48, title: 'Daftar Upah Diperiksa', paragraphs: ['Daftar upah tujuh pelayaran itu diperiksa silang dengan buku kas perusahaan feri dan selisihnya terbukti. Orang yang dipanggil pada sidang pertama tidak lagi menyangkal. Ia menyebut dua nama lain sebagai pemberi perintah. Perkara berpindah ke tangan pemeriksa pusat dalam bentuk berkas bernomor.'] },
      { chapterNumber: 49, title: 'Sarapan Tanpa Membelakangi', paragraphs: ['Pagi setelah berkas diserahkan, keduanya sarapan menghadap pintu yang sama dan Sari mengakui bahwa dahulu ia menuduh adiknya karena lebih mudah daripada menuduh orang kantor. Latif berkata pengakuan tersebut telah lama dinantikannya. Mereka menghabiskan sarapan tanpa terburu-buru, lalu mencuci kedua piring bersama sebelum kembali bekerja.'] },
      { chapterNumber: 50, title: 'Genting Diganti Seluruhnya', paragraphs: ['Uang penggantian upah tujuh pelayaran keluar dan awak itu membagi sebagian untuk mengganti genting rumah mereka. Latif kembali bekerja di feri dengan jam tercatat pada kartu. Sari masih kehilangan giliran kerja satu pekan setiap bulan sebagai sisa hukumannya. Keduanya memasang genting baru sepanjang sore.'] },
    ], justification: 'The sibling conflict moves from a stalled kitchen argument to firsthand observation, a named source, and shared exposure, then the runway makes both pay — stoned roof, seized ledger, a month of suspension, a refused city job — before Sari names her own displaced blame and the wage debt is finally paid.' },
    { chapters: [
      { chapterNumber: 6, title: 'Warung Dibuka Kembali', paragraphs: ['Warung dermaga dibuka kembali setelah tutup dua bulan karena pemiliknya sakit. Nyi Ratih memasang tirai baru dan menata bangku panjang menghadap laut. Kuli bongkar berdatangan sejak subuh. Sari melewatinya sambil membaca berkas dan hanya mengangguk kepada perempuan yang berdiri di depan tungku.'] },
      { chapterNumber: 14, title: 'Menolak Kopi Ratih', paragraphs: ['Sari menolak duduk di warung Nyi Ratih karena takut dilihat orang kantor izin. Ia menerima kopi sambil berdiri di luar lalu pergi. Nyi Ratih tidak bertanya alasannya. Jarak yang ia jaga hari itu membuat percakapan tentang karcis feri ganjil berhenti sebelum sempat dimulai.'] },
      { chapterNumber: 15, title: 'Datang Saat Hujan', paragraphs: ['Hujan deras memaksa Sari masuk ke dalam warung, dan ia duduk di bangku belakang bersama tiga kuli angkut. Percakapan yang dulu tertunda berlanjut, kali ini dengan tambahan cerita seorang kuli tentang peti yang diangkut sebelum subuh. Kedekatan itu memberi keterangan yang tidak pernah ia peroleh dari luar pintu.'] },
      { chapterNumber: 16, title: 'Meminjam Meja Belakang', paragraphs: ['Sari meminta izin memakai meja belakang warung untuk menyalin catatan setiap malam. Nyi Ratih memberikan kunci pintu samping tanpa ditanya balik. Tempat yang semula ia hindari berubah menjadi ruang kerja rahasia, dan hubungan mereka berpindah dari pembeli-penjual menjadi dua orang yang menanggung risiko sama.'] },
      { chapterNumber: 32, title: 'Menjaga Warung Dibongkar', paragraphs: ['Ketika petugas datang membongkar warung, Sari berdiri di depan pintu samping bersama Nyi Ratih dan menyebut dirinya penyewa meja belakang. Nama itu masuk ke berita acara. Penghindaran pada hari pertama telah berubah menjadi kesediaan berdiri di kertas yang sama dengan perempuan tersebut.'] },
      { chapterNumber: 41, title: 'Berita Acara Digugat', paragraphs: ['Nyi Ratih menggugat berita acara pembongkaran dengan alasan warungnya berdiri di tanah sewa yang izinnya masih berlaku empat tahun. Sari menyerahkan salinan perjanjian sewa meja belakang sebagai bukti pendukung. Berkas gugatan diterima pengadilan kecil. Bongkaran dihentikan sementara menunggu putusan. Sidang perdananya dijadwalkan pada pekan ketiga bulan tersebut.'] },
      { chapterNumber: 42, title: 'Meja Belakang Disegel', paragraphs: ['Meja belakang tempat Sari menyalin catatan disegel sebagai bagian tempat sengketa, dan seluruh isinya diinventaris. Catatan salinan tujuh bulan tercantum dalam daftar sitaan. Sari kehilangan akses ke ruang kerjanya. Ia memindahkan pekerjaan menyalin ke kamar kosnya yang tidak berjendela. Lampu kamar tersebut padam sendiri setiap pukul sepuluh malam.'] },
      { chapterNumber: 43, title: 'Kuli Menolak Bersaksi', paragraphs: ['Tiga kuli yang dahulu bercerita di bangku belakang menolak menjadi saksi karena khawatir jatah kerja mereka dicabut. Nyi Ratih menerima keputusan tersebut tanpa memaksa. Sari juga menahan keinginan untuk membujuk. Gugatan akhirnya berjalan berbekal dokumen saja, tanpa dukungan keterangan lisan dari para pekerja.'] },
      { chapterNumber: 44, title: 'Sewa Tanah Dipalsukan', paragraphs: ['Pemeriksa menemukan bahwa perjanjian sewa tanah warung memiliki dua versi dengan tanggal berbeda dan cap lilin yang tidak sama. Versi kedua muncul dari arsip kantor izin. Sari mengenali lekuk cap yang pernah ia bandingkan dahulu. Perkara warung bersambung dengan perkara berat garam.'] },
      { chapterNumber: 45, title: 'Ratih Menolak Damai', paragraphs: ['Kantor izin menawarkan pemindahan warung ke lokasi lain beserta ganti rugi bila gugatan dicabut. Nyi Ratih menanyakan apakah tawaran itu mengakui cap yang dipalsukan. Petugas menjawab tidak. Perempuan itu menolak tawaran tersebut di hadapan Sari dan meminta gugatan diteruskan. Petugas mencatat penolakan tersebut pada lembar terpisah.'] },
      { chapterNumber: 46, title: 'Kos Sari Digeledah', paragraphs: ['Kamar kos Sari digeledah dengan surat tugas yang menyebut dugaan penyimpanan dokumen negara. Petugas mengambil dua buku salinan dan meninggalkan sisanya berserakan. Sari mencatat nomor surat tugas itu sebelum petugas pergi. Malam itu ia menyalin ulang dari ingatan sampai subuh.'] },
      { chapterNumber: 47, title: 'Putusan Ditunda Lagi', paragraphs: ['Putusan pengadilan kecil ditunda untuk ketiga kalinya karena berkas cap lilin dinyatakan belum lengkap. Nyi Ratih mulai kehabisan uang untuk membayar juru tulis gugatan. Sari menyerahkan upahnya dua bulan tanpa memberi tahu siapa pun. Warung tetap tutup selama masa penundaan tersebut.'] },
      { chapterNumber: 48, title: 'Dua Cap Dibandingkan', paragraphs: ['Ahli dari kota membandingkan kedua cap lilin di hadapan hakim dan menyatakan versi kedua dibuat memakai cetakan yang berbeda. Nama pemesan cetakan itu dibacakan dari keterangan tukang cap. Regent Damar tidak hadir pada persidangan tersebut. Bongkaran warung dibatalkan pada hari yang sama.'] },
      { chapterNumber: 49, title: 'Duduk di Bangku Depan', paragraphs: ['Setelah putusan, Sari memilih tempat duduk paling depan pada warung yang dahulu ia hindari dan mengakui kepada Nyi Ratih bahwa ia dulu takut namanya bersanding dengan nama perempuan itu. Nyi Ratih menuang kopi dan berkata bahwa ketakutan itu wajar. Keduanya memandangi laut sampai lampu suar menyala.'] },
      { chapterNumber: 50, title: 'Warung Buka Subuh', paragraphs: ['Warung dibuka lagi pada subuh berikutnya dengan tirai yang sama dan bangku yang bertambah dua. Sari membayar sewa meja belakang seperti penyewa lain, tercatat dalam buku bersampul kain. Upah dua bulan yang ia serahkan tidak pernah ia sebut. Nyi Ratih menuliskan namanya di baris pertama buku itu.'] },
    ], justification: 'The relationship shifts through four physical arrangements, then the runway makes it costly on both sides — sealed workspace, a raided room, two months of wages given away, witnesses who refuse — and the false wax seal ties the stall case to the salt case before Sari names her old fear aloud.' },
    { chapters: [
      { chapterNumber: 6, title: 'Lilin Jatuh Dermaga', paragraphs: ['Sebuah cap lilin biru jatuh dari berkas yang dibawa lari angin dan pecah menjadi tiga bagian di papan dermaga. Kuli bongkar menyapunya ke tepi bersama serpihan kayu. Sari memungut satu pecahan terbesar ketika tidak ada yang memperhatikan. Ia memasukkannya ke saku tanpa tahu apa yang akan ia lakukan.'] },
      { chapterNumber: 14, title: 'Menyimpan Pecahan Lilin', paragraphs: ['Sari menyimpan pecahan cap lilin biru di kaleng bekas serta merahasiakannya dari seluruh penghuni dermaga. Ia hanya membandingkan warnanya dengan cap resmi di loket dari kejauhan. Kesimpulannya berhenti pada dugaan. Pecahan itu tinggal sebagai benda pribadi yang tidak dapat menjelaskan apa pun kepada orang lain.'] },
      { chapterNumber: 15, title: 'Mencari Tukang Cap', paragraphs: ['Sari menempuh jalan pantai ke rumah tukang cetak cap di kampung sebelah dan menunjukkan pecahan itu. Lelaki tua tersebut mengenali cetakan buatannya sendiri lalu menyebut siapa yang memesannya tiga musim lalu. Benda diam itu kini memiliki asal-usul dan sebuah nama yang dapat ditanyakan.'] },
      { chapterNumber: 16, title: 'Mencocokkan Dua Cap', paragraphs: ['Dengan izin Pak Uweng, Sari menempelkan pecahan tersebut pada berkas gudang berstempel resmi dan memotretnya dengan menggambar garis tepi di kertas kalkir. Perbedaan lekuk terlihat jelas. Dugaan pribadi berubah menjadi perbandingan fisik yang dapat dilihat siapa pun tanpa perlu percaya kepada ingatannya.'] },
      { chapterNumber: 32, title: 'Menyerahkan Dua Bukti', paragraphs: ['Sari menyerahkan pecahan lilin, kertas kalkir, dan keterangan tukang cap kepada pemeriksa pusat dalam satu bungkus bertanggal. Regent Damar menyebut benda itu sampah dermaga, tetapi pemeriksa mencatat nomor bungkusnya. Benda yang dulu bersembunyi di kaleng kini berdiri sebagai barang bukti bernomor.'] },
      { chapterNumber: 41, title: 'Tukang Cap Dipanggil', paragraphs: ['Tukang cetak cap dipanggil ke pemeriksaan dan menempuh jalan pantai selama empat jam dengan kaki yang sudah sulit berjalan. Ia mengenali cetakannya sendiri di depan pemeriksa dan menyebut nama pemesan. Sari membayar ongkos pulangnya. Lelaki tua itu meminta agar namanya tidak ditempel di papan mana pun.'] },
      { chapterNumber: 42, title: 'Cetakan Lama Dicari', paragraphs: ['Cetakan cap yang dipesan tiga musim lalu dicari ke bengkel, rumah pemesan, dan gudang kantor izin. Semuanya kosong. Tukang cap menyebutkan bahwa cetakan seperti itu biasanya dilebur bila tidak dipakai lagi. Pemeriksa mencatat kehilangan tersebut sebagai keterangan, bukan sebagai kebuntuan.'] },
      { chapterNumber: 43, title: 'Kalkir Dinyatakan Lemah', paragraphs: ['Kertas kalkir buatan Sari dinyatakan lemah sebagai bukti karena garis tepinya digambar tangan tanpa alat ukur baku. Ia menerima penilaian itu tanpa membantah. Pak Uweng menyarankan pengukuran ulang memakai jangka gudang. Pengukuran kedua dilakukan disaksikan dua petugas dan dicatat dalam berita acara.'] },
      { chapterNumber: 44, title: 'Pecahan Nyaris Hilang', paragraphs: ['Bungkus bertanggal berisi pecahan lilin sempat tidak ditemukan selama dua hari di ruang penyimpanan bukti. Sari mendatangi ruangan itu setiap pagi sampai bungkusnya muncul di rak yang salah. Ia meminta pemindahan ke lemari berkunci. Permintaan tersebut dikabulkan setelah ia mengajukannya tertulis.'] },
      { chapterNumber: 45, title: 'Damar Menyebut Sampah', paragraphs: ['Regent Damar mengulang di depan sidang bahwa benda itu hanyalah sampah dermaga yang dipungut orang iseng. Sari membacakan berita acara pengukuran jangka dan nomor lemari penyimpanan. Ruang sidang diam beberapa saat. Kalimat sampah dermaga tercatat dalam notulen sebagai keterangan resmi lelaki tersebut.'] },
      { chapterNumber: 46, title: 'Berkas Sewa Dicocokkan', paragraphs: ['Pemeriksa mencocokkan lekuk cap pada berkas sewa tanah warung dengan pecahan di lemari berkunci dan menemukan kesamaan pada tiga titik. Sari tidak diminta hadir pada pencocokan tersebut. Hasilnya disampaikan tertulis kepada semua pihak. Dua perkara yang berjalan terpisah kini memiliki satu benda penghubung.'] },
      { chapterNumber: 47, title: 'Kaleng Bekas Diminta', paragraphs: ['Pemeriksa meminta kaleng bekas tempat pecahan itu disimpan sebagai keterangan tentang bagaimana benda tersebut dirawat. Sari menyerahkannya beserta karat di bagian dasarnya. Kaleng itu satu-satunya benda peninggalan ayahnya yang masih ia simpan. Ia tidak menyebutkan hal tersebut kepada siapa pun di ruangan.'] },
      { chapterNumber: 48, title: 'Pemesan Cap Mengaku', paragraphs: ['Pemesan cetakan itu akhirnya mengaku setelah dihadapkan pada keterangan tukang cap dan hasil pencocokan lekuk. Ia menyebut dirinya hanya menjalankan perintah dan menyerahkan catatan pembayaran. Catatan tersebut memuat tanggal dan jumlah. Perkara cap lilin ditutup dan diteruskan sebagai perkara perintah.'] },
      { chapterNumber: 49, title: 'Kaleng Dikembalikan Kosong', paragraphs: ['Kaleng bekas itu dikembalikan kepada Sari dalam keadaan kosong setelah perkara ditutup. Ia duduk lama memegangnya di gudang garam dan mengakui kepada Bu Hasnah bahwa benda itu disimpannya sebab hanya peninggalan tersebut yang masih tersisa. Perempuan itu mendengarkan tanpa memotong. Sari menaruh kaleng tersebut di rak, bukan di kolong.'] },
      { chapterNumber: 50, title: 'Cap Baru Dibagikan', paragraphs: ['Seluruh gudang menerima cap lilin model baru dengan nomor seri yang dicatat dalam buku tersendiri. Tukang cetak tua meninggal dua bulan sebelum pembagian; sesuai permintaannya, kantor tidak mengumumkan namanya. Sari menandatangani penerimaan cap untuk gudang garam. Kaleng bekas tersebut tetap berdiri pada rak kamarnya.'] },
    ], justification: 'The wax fragment advances through concealment, sourcing, comparison, and numbered submission, then the runway has her tracing rejected as weak, the fragment nearly lost, the tin surrendered, and finally the seal linking two cases — with the old engraver dead unnamed and Sari admitting why she hoarded it.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 6, title: 'Selisih Pertama Terlihat', paragraphs: ['Sari menemukan selisih berat karung garam antara berkas dan tumpukan yang ia lihat di gudang. Ia menyebutkannya kepada kuli bongkar yang lewat dan orang itu mengangkat bahu. Tidak ada yang dituliskan pada hari tersebut. Selisih itu tinggal sebagai hal yang ia ketahui sendiri sepanjang musim.'] },
      { chapterNumber: 14, title: 'Menuntut di Loket', paragraphs: ['Sari berdiri di depan loket izin dan menuntut penjelasan tentang selisih berat karung garam. Petugas menjawab bahwa semua sudah sesuai aturan. Sari meninggikan suara sebentar lalu pergi. Tidak ada catatan yang berpindah tangan, dan berkas sore itu tetap disahkan seperti pagi harinya.'] },
      { chapterNumber: 15, title: 'Menuntut Lagi Sama', paragraphs: ['Keesokan harinya Sari kembali ke loket yang sama dan menuntut penjelasan yang sama dengan kalimat yang hampir tidak berubah. Petugas mengulang jawabannya. Suaranya kembali naik beberapa saat sebelum ia berbalik pergi. Tidak ada dokumen baru, tidak ada saksi, dan selisih berat masih hanya ada di kepalanya.'] },
      { chapterNumber: 16, title: 'Menuntut Ketiga Kali', paragraphs: ['Tuntutan itu diulang untuk ketiga kalinya di loket yang sama pada jam yang sama. Jawaban petugas tidak bergeser satu kata pun. Sari pergi dengan kemarahan yang sama seperti dua hari sebelumnya, membawa pengetahuan yang tidak bertambah dan hubungan yang tidak berubah.'] },
      { chapterNumber: 32, title: 'Menuntut Sekali Lagi', paragraphs: ['Berbulan kemudian Sari mendatangi loket tersebut dan mengucapkan tuntutan itu lagi. Petugasnya berganti orang, tetapi kalimat jawabannya diambil dari lembar aturan yang sama. Sari pulang tanpa satu pun kertas, sementara berkas sore kembali disahkan dan selisih berat tetap hanya tersimpan di kepalanya.'] },
      { chapterNumber: 41, title: 'Loket Dituntut Pagi', paragraphs: ['Sari datang pagi-pagi ke loket izin dan mengucapkan tuntutan yang sama sebelum antrean panjang terbentuk. Petugas membaca lembar aturan yang sama dari laci yang sama. Suaranya naik sebentar lalu ia berbalik pergi. Berkas pagi disahkan tepat waktu dan tidak ada kertas yang berpindah tangan.'] },
      { chapterNumber: 42, title: 'Loket Dituntut Siang', paragraphs: ['Siang harinya ia kembali ke jendela kayu itu dan mengulang kalimat yang sama tentang selisih berat karung. Jawabannya tidak bergeser satu kata. Sari berdiri agak lebih lama sebelum pergi. Selisih itu masih hanya tersimpan di kepalanya seperti pada musim pertama ia melihatnya.'] },
      { chapterNumber: 43, title: 'Loket Dituntut Sore', paragraphs: ['Menjelang tutup, Sari mengucapkan tuntutan tersebut sekali lagi kepada petugas yang sedang membereskan meja. Lelaki itu menyebut lembar aturan tanpa membukanya. Sari pulang menyusuri dermaga seperti biasa. Tidak ada saksi, tidak ada catatan, dan tidak ada janji apa pun yang dibuat.'] },
      { chapterNumber: 44, title: 'Loket Dituntut Hujan', paragraphs: ['Hujan turun deras dan Sari tetap datang ke loket dengan berkas terlindung plastik. Ia mengulang kalimat yang sama sambil menyeka air dari lengannya. Petugas menjawab persis seperti sebelumnya. Berkas sore disahkan dan ia pulang membawa pengetahuan yang jumlahnya sama seperti pagi tadi.'] },
      { chapterNumber: 45, title: 'Loket Dituntut Ramai', paragraphs: ['Antrean panjang tidak menolong ketika Sari mengucapkan tuntutan yang sama di depan banyak orang. Beberapa yang mengantre menoleh sebentar lalu kembali menunduk. Petugas membaca kalimat aturan yang sudah dihafal Sari. Ia keluar dari barisan tanpa satu pun kertas di tangannya.'] },
      { chapterNumber: 46, title: 'Loket Dituntut Sepi', paragraphs: ['Pada hari sepi Sari mencoba lagi, berharap ketiadaan pendengar membuat jawaban berubah. Petugas hanya memperlunak nada ketika mengulang kalimat lama. Sari mengangguk lalu pergi. Sari keluar tanpa dokumen maupun nama di tangan. Petugas merapikan tumpukan lembar di mejanya, lalu seekor camar bertengger pada palang loket sampai ruangan ditutup.'] },
      { chapterNumber: 47, title: 'Loket Dituntut Kembali', paragraphs: ['Sari mengulangi tuntutan tersebut setelah dua pekan tidak datang, dengan kalimat yang tidak ia ubah sama sekali. Petugas mengenali wajahnya dan langsung menyebut nomor pasal. Percakapan selesai dalam waktu singkat. Berkas sore disahkan seperti seluruh sore sebelumnya di pelabuhan tersebut.'] },
      { chapterNumber: 48, title: 'Loket Dituntut Lagi', paragraphs: ['Ia berdiri di depan jendela kayu itu dan mengucapkannya sekali lagi tanpa membawa apa pun untuk ditunjukkan. Petugas menjawab tanpa mengangkat kepala dari berkasnya. Sari pergi setelah beberapa saat. Selisih berat karung tetap berada di kepalanya seperti bertahun-tahun sebelumnya.'] },
      { chapterNumber: 49, title: 'Pulang Melewati Suar', paragraphs: ['Sari pulang melewati kaki menara suar seperti setiap sore dan berpikir bahwa besok ia akan datang lagi. Ia tidak menyebutkan perasaannya kepada siapa pun di rumah. Latif bertanya bagaimana harinya dan ia menjawab biasa saja. Malam itu berakhir seperti seluruh malam pada musim tersebut.'] },
      { chapterNumber: 50, title: 'Musim Ditutup Sama', paragraphs: ['Upacara kecil di halaman pelabuhan menutup musim garam, sementara berkas terakhir disahkan tanpa keberatan tertulis. Sari menyaksikan dari ujung kerumunan. Sesudah acara, tuntutan lamanya kembali menerima jawaban lama dari petugas. Selisih berat karung tetap menjadi pengetahuan pribadi yang tidak pernah ia keluarkan.'] },
    ], justification: 'The same demand is made at the same window ten times with no change of tactic, information, relationship, or outcome; the closing chapters restate the identical exchange and the weight discrepancy never leaves her head.' },
    { chapters: [
      { chapterNumber: 6, title: 'Peti Pertama Naik', paragraphs: ['Peti tanpa berkas muatan pertama kali naik ke feri malam melalui pintu belakang dan Latif ikut mengangkatnya bersama dua awak lain. Ia menceritakannya di dapur sambil makan. Sari mendengarkan tanpa berkomentar apa pun malam itu. Keduanya tidur setelah lampu dapur dimatikan seperti biasa.'] },
      { chapterNumber: 14, title: 'Bertengkar Soal Peti', paragraphs: ['Sari dan Latif bertengkar di dapur sempit mereka tentang peti yang naik ke feri tanpa berkas muatan. Adiknya membela diri dengan suara tertahan, Sari menuduh sambil menunjuk pintu belakang, lalu keduanya memilih diam. Lampu dimatikan tanpa kesimpulan apa pun. Esok paginya mereka sarapan seperti biasa dan tidak seorang pun menyinggung peti tersebut.'] },
      { chapterNumber: 15, title: 'Bertengkar Lagi Malam', paragraphs: ['Pertengkaran serupa berulang di dapur pada malam berikutnya dengan tuduhan dan pembelaan yang sama. Tidak ada nama orang kantor yang disebut, tidak selembar bukti dibuka di atas meja, dan tidak satu janji pun dibuat. Lampu dapur dimatikan seperti kemarin, lalu sarapan keesokan pagi berjalan seperti biasa.'] },
      { chapterNumber: 16, title: 'Bertengkar Tanpa Ujung', paragraphs: ['Untuk ketiga kalinya kalimat yang sama saling dilemparkan di ruang yang sama. Latif tetap membawa peti lewat pintu belakang, Sari tetap menuduh tanpa bukti, dan keduanya tetap tidur di kamar yang sama. Tidak ada satu pun keterangan baru yang masuk ke rumah tersebut sepanjang pekan.'] },
      { chapterNumber: 32, title: 'Bertengkar Musim Berikut', paragraphs: ['Musim berganti dan pertengkaran itu terjadi lagi tanpa perbedaan berarti. Peti masih naik melalui jalur belakang kapal, tuduhan masih berupa dugaan tanpa angka, dan diam masih menjadi penutup malam mereka. Hubungan kakak-adik itu berhenti pada bentuk yang sama seperti tiga percakapan sebelumnya.'] },
      { chapterNumber: 41, title: 'Menuduh Sebelum Makan', paragraphs: ['Sari menuduh adiknya sebelum piring diletakkan dan Latif membela diri dengan alasan semua awak melakukannya. Keduanya berhenti berbicara ketika nasi habis. Tidak ada nama yang disebut dan tidak ada angka yang dituliskan. Lampu dapur dimatikan lalu mereka tidur membelakangi seperti biasanya.'] },
      { chapterNumber: 42, title: 'Menuduh Setelah Makan', paragraphs: ['Kali ini tuduhan itu diucapkan setelah makan selesai, dengan kalimat yang sama tentang peti dan pintu belakang. Latif menjawab dengan pembelaan yang sudah dihafal Sari. Piring dicuci dalam keadaan diam. Bukti tetap tersimpan, sementara identitas pegawai kantor tidak pernah disebut.'] },
      { chapterNumber: 43, title: 'Menuduh di Halaman', paragraphs: ['Pertengkaran berpindah ke halaman rumah karena dapur terasa panas, tetapi isinya tidak berubah sama sekali. Sari menunjuk arah dermaga, Latif menyebut semua awak, dan keduanya berhenti setelah tetangga menutup jendela. Mereka masuk ke rumah tanpa kesepakatan. Peti masih naik lewat pintu belakang pada malam berikutnya.'] },
      { chapterNumber: 44, title: 'Menuduh Sambil Bekerja', paragraphs: ['Sambil menggulung tali di halaman, Sari kembali menuduh Latif yang terus bekerja ketika menjawab. Sari menyebut peti tanpa berkas, lalu Latif menjawab bahwa semua awak mengangkat muatan serupa. Saat gulungan selesai, suara mereka pun berhenti. Pekan itu peti masih melewati pintu belakang.'] },
      { chapterNumber: 45, title: 'Menuduh Malam Hujan', paragraphs: ['Hujan menahan mereka di rumah hingga tuduhan lama kembali terdengar menjelang tengah malam. Latif menjawab pelan agar tetangga tidak mendengar. Beberapa saat kemudian keduanya memilih diam. Pagi berikutnya, sarapan berlangsung dalam kebiasaan lama; peti itu sama sekali tidak menjadi bahan percakapan.'] },
      { chapterNumber: 46, title: 'Menuduh Depan Pintu', paragraphs: ['Sari menghadang adiknya di pintu dan melontarkan tuduhan sebelum Latif melepas sepatu. Jawaban yang diterima tidak berbeda dari malam-malam terdahulu. Mereka masuk tanpa meneruskan pertengkaran. Latif menggantung bajunya, Sari menaruh piring di meja, dan keduanya tidur sebelum nama pegawai kantor sempat disebut.'] },
      { chapterNumber: 47, title: 'Menuduh Sesudah Subuh', paragraphs: ['Pada subuh setelah penyeberangan malam, Sari mengulang kalimat yang sama ketika adiknya baru pulang. Latif terlalu lelah untuk membantah panjang dan hanya menyebut bahwa semua awak melakukannya. Keduanya tidur pada jam yang berbeda. Peti tetap naik melalui jalur belakang pada malam berikutnya.'] },
      { chapterNumber: 48, title: 'Menuduh Tanpa Angka', paragraphs: ['Sekali lagi tuduhan muncul tanpa angka, tanggal, ataupun identitas yang dapat diperiksa. Ketika Latif meminta bukti, Sari hanya menjawab bahwa matanya sendiri telah melihat. Percakapan kembali buntu. Sesudah lampu dapur dipadamkan, mereka berbaring saling membelakangi dalam satu kamar. Suara feri malam masuk melalui celah jendela yang belum ditutup.'] },
      { chapterNumber: 49, title: 'Diam di Kamar Sama', paragraphs: ['Malam itu tuduhan tidak terdengar; hanya keheningan serupa penutup seluruh pertengkaran terdahulu. Sari menyusun sebuah kalimat dalam pikiran, tetapi membiarkannya tidak terucap. Latif menghadap dinding. Seperti sejak awal musim, kedua bersaudara itu tetap tidur dalam ruang yang mereka bagi. Angin laut menggerakkan tirai tipis di antara ranjang mereka.'] },
      { chapterNumber: 50, title: 'Musim Baru Peti Sama', paragraphs: ['Pada pembukaan musim baru, peti tanpa berkas kembali dinaikkan lewat pintu belakang feri malam. Sari melontarkan tuduhan lama pada malam pertama. Latif membalas dengan pembelaan yang telah berulang bertahun-tahun. Mereka memadamkan lampu dapur, lalu menjalani sarapan esok hari tanpa percakapan yang berbeda.'] },
    ], justification: 'The kitchen quarrel repeats in substance across ten chapters with only the location or hour shifted, producing no new fact, name, angka, or change between the siblings, and the final season opens with the identical exchange.' },
    { chapters: [
      { chapterNumber: 6, title: 'Malam Lampu Padam', paragraphs: ['Lampu suar padam selama hampir dua jam pada malam berangin dan dua perahu kecil kandas di beting. Sari melihatnya dari jendela kamar tanpa turun ke dermaga. Penjaga menara tidak pernah menjelaskan apa yang terjadi. Malam itu tersimpan di ingatannya tanpa satu pun tanggal yang ia tuliskan.'] },
      { chapterNumber: 14, title: 'Memandangi Menara', paragraphs: ['Sari berdiri di kaki menara suar dan memandangi lampunya yang berputar. Ia teringat malam ketika lampu itu padam. Tidak ada yang ia tanyakan kepada penjaga, dan tidak ada catatan yang ia buka. Ia pulang membawa perasaan yang sama seperti ketika datang.'] },
      { chapterNumber: 15, title: 'Memandangi Sekali Lagi', paragraphs: ['Pada senja berikutnya Sari kembali berdiri di tempat yang sama dan memandangi lampu yang sama. Ingatan tentang malam padam muncul lagi dengan kata-kata yang serupa. Penjaga menara lewat tanpa disapa, dan buku minyak lampu tetap tersimpan di rak dalam.'] },
      { chapterNumber: 16, title: 'Memandangi Dari Jauh', paragraphs: ['Kali ini Sari memandanginya dari ujung dermaga, meski isi pikirannya tidak bergeser. Ia menyebut dalam hati bahwa suatu hari akan menanyakan tanggalnya. Hari itu tidak datang. Tidak ada percakapan, tidak ada lembar disalin, dan isi kepalanya sama persis seperti senja pertama.'] },
      { chapterNumber: 32, title: 'Memandangi Musim Kering', paragraphs: ['Pada musim kering Sari sekali lagi berdiri memandangi menara. Kalimat dalam hatinya masih sama dan janji untuk bertanya masih tertunda. Lampu suar berputar seperti biasa di atas kepalanya. Keempat kunjungan tersebut tidak menambahkan satu pun keterangan pada perkara berat garam yang sedang ia bawa ke mana-mana.'] },
      { chapterNumber: 41, title: 'Berdiri Senja Berangin', paragraphs: ['Senja berangin membawa Sari kembali ke dasar menara sambil merapatkan kerah baju. Malam ketika cahaya suar padam terlintas lagi, tetapi hanya sebagai pikiran lama. Pintu besi ditutup penjaga dari dalam. Sari meninggalkan tempat tersebut tanpa mengajukan pertanyaan maupun mengeluarkan catatan dari tasnya.'] },
      { chapterNumber: 42, title: 'Berdiri Sesudah Kerja', paragraphs: ['Usai bekerja, Sari mendatangi pelataran menara untuk menyaksikan sorot cahaya berkeliling. Ia kembali membayangkan tanggal malam padam tersimpan dalam buku minyak di ruangan dalam. Tidak ada upaya mengambil buku tersebut. Ketika beranjak pulang, perasaannya belum berbeda dibanding saat baru tiba.'] },
      { chapterNumber: 43, title: 'Berdiri Bawa Berkas', paragraphs: ['Berkas bongkaran berada dalam genggaman Sari saat ia kembali menatap cahaya menara. Map tersebut tetap tertutup sepanjang kunjungan. Penjaga melintas dengan kaleng minyak tanpa menerima sapaan. Pikiran Sari tidak menghasilkan apa pun selain bayangan lama dari kedatangannya yang pertama. Ujung map melengkung terkena udara lembap selama ia berdiri.'] },
      { chapterNumber: 44, title: 'Berdiri Setelah Hujan', paragraphs: ['Sesudah hujan mereda, Sari berhenti pada papan dermaga yang masih basah. Kenangan tentang cahaya padam dan dua perahu kandas kembali berputar tanpa terucap. Ia tidak mendekati penjaga atau menyalin buku apa pun. Jalan pulang yang biasa ditempuhnya kembali menjadi akhir kunjungan tersebut.'] },
      { chapterNumber: 45, title: 'Berdiri Sambil Menunggu', paragraphs: ['Sambil menunggu kapal terakhir, Sari bertahan dekat menara dan mengikuti putaran cahaya dengan mata. Keinginan menanyakan tanggal kembali timbul, lalu hilang ketika kapal merapat. Ia bergegas menuju dermaga. Sepanjang sisa musim, buku minyak tidak pernah disebutnya dalam percakapan dengan siapa pun.'] },
      { chapterNumber: 46, title: 'Berdiri Pagi Buta', paragraphs: ['Pagi buta dipilih Sari karena penjaga mungkin lebih mudah ditemui sebelum kerja dimulai. Namun ia tetap terpaku menyaksikan lampu perlahan dipadamkan. Pintu besi sempat terbuka, kemudian menutup kembali tanpa ia dekati. Sari memasukkan kedua tangan ke saku dan pulang sebelum penjaga menyalakan lampu ruang dalam.'] },
      { chapterNumber: 47, title: 'Berdiri Membawa Pena', paragraphs: ['Pena dan secarik kertas ikut dibawa Sari menuju menara, tetapi keduanya hanya digenggam saat cahaya berputar. Tidak satu kata pun lahir pada permukaan kertas. Ia melipatnya kembali ke saku sebelum pulang. Malam padam tersebut tetap tidak memperoleh tanggal atau penjelasan tambahan.'] },
      { chapterNumber: 48, title: 'Berdiri Terakhir Musim', paragraphs: ['Hari penutup musim garam kembali menemukan Sari di pelataran menara dengan pikiran lama. Pertanyaan masih dijanjikan untuk waktu mendatang, bukan diucapkan saat itu. Musim berakhir sebelum janji tersebut dijalankan. Ia membawa pulang perkara berat garam tanpa tambahan keterangan dari kunjungan terakhir itu.'] },
      { chapterNumber: 49, title: 'Menyebut Kepada Diri', paragraphs: ['Sari memperpanjang waktu berdiri malam itu sampai mengakui dalam pikiran bahwa pertanyaan mungkin tidak pernah terucap. Pengakuan tersebut tidak dibagikan kepada Latif atau Bu Hasnah. Cahaya terus beredar di atasnya. Setelah pulang, ia langsung tidur tanpa meninggalkan satu baris catatan.'] },
      { chapterNumber: 50, title: 'Lampu Berputar Seperti Dahulu', paragraphs: ['Ketika musim kering berikutnya datang, Sari sekali lagi menatap putaran suar sambil menyimpan pertanyaan lama. Buku minyak tetap berada pada rak ruangan dalam. Penjaga menutup pintu besi menjelang gelap, dan Sari pulang tanpa menanyakan tanggal padam atau membuka kertas di sakunya.'] },
    ], justification: 'Ten visits to the lighthouse recycle the same reflection with no question asked, no record obtained, and no relationship touched; even the closing chapters only restate the unasked question.' },
    { chapters: [
      { chapterNumber: 6, title: 'Tumpukan Sisi Timur', paragraphs: ['Sejak kapal jalur utara singgah dua kali sepekan, deretan peti ikan asin meninggi pada ujung timur pelabuhan. Sari melewati deretan tersebut setiap pagi menuju meja pencatatan. Ia belum mencoba menghitung muatannya. Berkas dari loket selalu tiba dengan jumlah yang sudah ditulis rapi.'] },
      { chapterNumber: 14, title: 'Menghitung Peti Ikan', paragraphs: ['Sari menghitung peti ikan asin di sisi timur dermaga dan menemukan jumlahnya lebih banyak dari berkas. Ia menyimpan angka itu di kepala. Tidak ada yang diberi tahu dan tidak ada yang dituliskan. Peti-peti tersebut diangkut sebelum ia selesai berpikir.'] },
      { chapterNumber: 15, title: 'Menghitung Peti Kembali', paragraphs: ['Penghitungan yang sama diulang pada sisi dermaga yang sama keesokan harinya, dengan hasil selisih yang serupa. Sari kembali menyimpannya di dalam kepala tanpa mencatat apa pun. Berkas muatan tidak ia salin, Pak Uweng tidak ia temui di bak penimbang, dan peti tetap diangkut seperti biasa menjelang siang.'] },
      { chapterNumber: 16, title: 'Menghitung Peti Ketiga', paragraphs: ['Untuk ketiga kalinya Sari berdiri di tepi tumpukan itu dan menghitung tanpa membawa alat tulis. Angka selisih itu berputar di kepalanya persis seperti dua hari sebelumnya. Tidak seorang pun menyaksikan, tidak selembar pun disalin, dan tidak satu langkah lanjutan ia ambil sebelum derek berhenti.'] },
      { chapterNumber: 32, title: 'Menghitung Peti Terakhir', paragraphs: ['Berbulan setelahnya Sari kembali menghitung di tempat yang sama lalu menemukan pola selisih serupa. Ia tetap enggan menuliskannya, tetap merahasiakannya dari seisi dermaga, dan tetap membiarkan peti diangkut. Empat penghitungan itu berakhir sebagai pengetahuan yang tidak pernah keluar dari kepalanya.'] },
      { chapterNumber: 41, title: 'Menghitung Sebelum Derek', paragraphs: ['Sari menghitung tumpukan itu sebelum derek mulai bekerja dan memperoleh selisih yang serupa dengan hitungan lamanya. Ia menyimpannya di kepala tanpa membawa alat tulis. Kuli bongkar mulai mengangkut sebelum ia selesai memastikan. Sepanjang hari, hasil hitungan tersebut tetap tidak diberitahukan kepada siapa pun.'] },
      { chapterNumber: 42, title: 'Menghitung Sambil Berjalan', paragraphs: ['Kali ini ia menghitung sambil berjalan melewati tumpukan agar tidak terlihat sedang memeriksa. Hasilnya sama seperti hitungan sebelumnya dan tetap tidak ia tuliskan. Pak Uweng berdiri di bak penimbang tanpa ia datangi. Peti-peti itu diangkut menjelang siang seperti hari-hari sebelumnya.'] },
      { chapterNumber: 43, title: 'Menghitung Dari Gudang', paragraphs: ['Sari menghitung dari undakan pintu gudang karena posisinya lebih tinggi dan tumpukan terlihat seluruhnya. Angka selisih yang ia peroleh serupa dengan sebelumnya. Ia tidak menyalin berkas muatan dan tidak menemui siapa pun. Peti-peti tersebut sudah kosong dari dermaga sebelum ia turun dari undakan itu.'] },
      { chapterNumber: 44, title: 'Menghitung Dua Kali', paragraphs: ['Pada pagi yang sama Sari menghitung ulang seluruh tumpukan demi memastikan hasil pertama. Angka kedua cocok, tetapi tetap disimpan dalam ingatan. Ia tidak membawa pensil atau mengajak saksi. Ketika derek bergerak, peti-peti berkurang satu per satu tanpa catatan baru dibuat.'] },
      { chapterNumber: 45, title: 'Menghitung Musim Hujan', paragraphs: ['Terpal menutupi sebagian tumpukan pada musim hujan, dan Sari tetap menghitung dari sela yang terbuka. Angkanya kembali menunjukkan selisih serupa. Ia berpikir untuk memberi tahu Pak Uweng lalu mengurungkannya. Peti-peti tersebut diangkut ketika hujan mereda menjelang siang. Terpalnya diikat kembali oleh dua kuli sebelum matahari muncul.'] },
      { chapterNumber: 46, title: 'Menghitung Tanpa Terpal', paragraphs: ['Terpal sudah dilepas dan seluruh tumpukan terlihat jelas ketika Sari menghitungnya lagi dari tepi. Hasilnya tidak berbeda dari penghitungan pada musim hujan. Ia menyimpannya di kepala seperti biasa. Berkas muatan hari itu ia sahkan tanpa mencantumkan satu pun catatan tambahan.'] },
      { chapterNumber: 47, title: 'Menghitung Sesudah Kapal', paragraphs: ['Setelah kapal jalur utara berangkat, Sari menghitung sisa peti yang belum diangkut dan menemukan pola selisih yang sama. Ia berdiri cukup lama memandangi tumpukan tersebut. Ia tidak membuat salinan atau menemui pekerja lain. Sisa peti diangkut esok paginya oleh kuli yang sama.'] },
      { chapterNumber: 48, title: 'Menghitung Pagi Buta', paragraphs: ['Sari datang pagi buta ketika dermaga masih sepi dan menghitung tumpukan itu tanpa terganggu siapa pun. Angka selisihnya kembali serupa dengan seluruh penghitungan sebelumnya. Ia tetap enggan menuliskannya di mana pun. Derek mulai bekerja ketika matahari naik dan peti-peti itu berkurang.'] },
      { chapterNumber: 49, title: 'Angka Berputar di Kepala', paragraphs: ['Malam itu angka selisih tersebut berputar di kepalanya ketika ia berbaring dan ia memutuskan bahwa besok pun ia tidak akan menuliskannya. Ia tidak menceritakannya kepada Latif yang tidur di kamar sebelah. Tidak ada perasaan yang ia sebutkan kepada siapa pun. Ia tertidur seperti malam-malam sebelumnya.'] },
      { chapterNumber: 50, title: 'Tumpukan Musim Berikut', paragraphs: ['Pada musim berikutnya, deretan ikan asin kembali memenuhi ujung timur pelabuhan. Sari melakukan hitungan dari dekat air dan memperoleh pola selisih lama. Hasil tersebut tidak dicatat atau disampaikan kepada pekerja lain. Seluruh peti tetap diangkut, sementara angkanya tinggal sebagai ingatan pribadi.'] },
    ], justification: 'The count is repeated ten times with the same method and the same dead end; nothing is ever recorded, shared, or used, and the last chapter reproduces the first count exactly.' },
    { chapters: [
      { chapterNumber: 6, title: 'Uweng Menerima Sari', paragraphs: ['Pak Uweng menerima Sari di bak penimbang pada hari pertama ia bekerja dan menunjukkan cara membaca jarum yang sudah aus. Ia berkata bahwa pekerjaan di pelabuhan menuntut kesabaran lebih daripada ketelitian. Sari mencatat kalimat itu di halaman pertama bukunya. Keduanya kembali bekerja sebelum derek berbunyi.'] },
      { chapterNumber: 14, title: 'Meminta Nasihat Uweng', paragraphs: ['Sari meminta nasihat Pak Uweng tentang cara menghadapi kantor izin. Juru timbang itu menyarankan bersabar sambil menunggu musim pemeriksaan tiba. Sari mengangguk lalu kembali ke meja catatnya. Tidak ada rencana yang disusun berdua dan tidak ada tanggal yang disebut dalam percakapan singkat tersebut.'] },
      { chapterNumber: 15, title: 'Meminta Nasihat Ulang', paragraphs: ['Percakapan serupa terjadi di dekat bak penimbang beberapa hari kemudian. Nasihatnya sama, jawaban Sari pun sama, dan keduanya kembali ke pekerjaan masing-masing sebelum derek berbunyi. Tidak selembar dokumen disiapkan sesudahnya, dan hubungan kerja mereka tetap persis seperti sebelum percakapan itu dimulai.'] },
      { chapterNumber: 16, title: 'Meminta Nasihat Sama', paragraphs: ['Untuk ketiga kalinya Sari menanyakan hal serupa dan menerima anjuran bersabar. Ia mengangguk seperti biasa lalu menyimpan penanya. Musim pemeriksaan tidak pernah disebut tanggalnya, langkah persiapan tidak pernah disusun di atas kertas, dan kedua orang itu tidak pernah menyepakati satu tindakan pun.'] },
      { chapterNumber: 32, title: 'Meminta Nasihat Lama', paragraphs: ['Jauh kemudian Sari mengulang pertanyaan yang sama dan Pak Uweng mengulang anjuran yang sama. Keduanya tertawa kecil menyadari kebiasaan lama itu, lalu kembali bekerja seperti hari-hari sebelumnya. Percakapan keempat tersebut berakhir tanpa menambah keterangan tentang berat garam, tanpa rencana bersama, dan tanpa kedekatan yang berbeda.'] },
      { chapterNumber: 41, title: 'Bertanya Dekat Timbangan', paragraphs: ['Ketika Pak Uweng membersihkan jarum timbangan, Sari meminta petunjuk menghadapi kantor izin. Jawabannya hanya anjuran menunggu pemeriksaan musim depan dengan sabar. Sari menerima ucapan itu dan kembali ke meja. Mereka tidak menentukan tanggal ataupun tindakan bersama. Setelah dilap, jarum timbangan kembali lurus.'] },
      { chapterNumber: 42, title: 'Bertanya Sesudah Derek', paragraphs: ['Sesudah bunyi derek berhenti, Sari kembali meminta petunjuk di dekat bak timbang. Pak Uweng memberi jawaban lama tentang kesabaran tanpa tambahan langkah. Mereka berpisah menuju tugas masing-masing. Tak ada dokumen disiapkan. Pak Uweng kembali ke bak penimbang, sedangkan Sari menuju meja catat tanpa melanjutkan percakapan.'] },
      { chapterNumber: 43, title: 'Bertanya Sambil Menunggu', paragraphs: ['Sambil menanti giliran timbang, Sari meminta saran lagi kepada Pak Uweng. Lelaki itu menjawab tanpa menoleh dari beban di bak; isinya masih sebatas permintaan agar sabar. Percakapan selesai tanpa kesepakatan tindakan. Antrean pekerja di belakang mereka sudah memanjang sampai pintu gudang.'] },
      { chapterNumber: 44, title: 'Bertanya Hari Sepi', paragraphs: ['Hari tanpa kapal memberi Sari waktu meminta jawaban lebih lengkap dari Pak Uweng. Namun juru timbang itu kembali menyuruhnya menunggu dengan sabar. Mereka duduk memandang dermaga kosong selama beberapa saat. Kertas di pangkuan Sari tetap kosong sampai keduanya berdiri. Ombak kecil menggoyangkan pelampung tambat di hadapan mereka ketika Pak Uweng kembali ke gudang.'] },
      { chapterNumber: 45, title: 'Bertanya Sesudah Hujan', paragraphs: ['Setelah hujan, Sari mengangkat persoalan kantor izin di bawah atap seng gudang. Pak Uweng mengulang anjuran lama tanpa rincian baru. Sari memasukkan pena ke saku dan menerima percakapan tersebut. Pemeriksaan hanya disebut sebagai musim, bukan tanggal. Keduanya lalu kembali bekerja.'] },
      { chapterNumber: 46, title: 'Bertanya Sambil Berjalan', paragraphs: ['Dalam perjalanan menuju gudang, Sari sekali lagi meminta arahan. Jawaban Pak Uweng begitu lama diulang hingga telah dihafalnya: tetap sabar dan menunggu. Mereka berhenti bicara saat mencapai pintu. Sesudahnya tidak muncul rencana bersama maupun lembar persiapan apa pun. Debu garam melekat pada sepatu mereka sampai langkah terakhir.'] },
      { chapterNumber: 47, title: 'Bertanya Menjelang Tutup', paragraphs: ['Sebelum gudang ditutup, Sari kembali meminta petunjuk yang belum pernah dijalankan. Pak Uweng menjawab dengan nada lelah bahwa ia perlu bersabar. Mereka mengunci pintu bersama, kemudian berpisah di simpang. Tak satu langkah persiapan tertulis lahir dari percakapan itu. Hanya sebagian lampu jalan menyala.'] },
      { chapterNumber: 48, title: 'Bertanya Sekali Lagi', paragraphs: ['Pertanyaan Sari kembali memperoleh jawaban spontan Pak Uweng tentang menunggu dengan sabar. Mereka sempat tertawa karena percakapan tersebut terasa terlalu dikenal. Sesudah tawa berhenti, Pak Uweng mengangkat karung berikutnya ke bak timbang. Sari kembali ke mejanya dengan pena masih tersimpan di saku.'] },
      { chapterNumber: 49, title: 'Menyimpan Kalimat Sendiri', paragraphs: ['Malam itu Sari memikirkan bahwa ia sebenarnya ingin mengatakan sesuatu yang lain kepada Pak Uweng, lalu memutuskan tidak mengucapkannya. Ia tidak menyebutkannya kepada Latif maupun kepada Bu Hasnah. Kalimat tersebut tetap berada di kepalanya. Ia tidur seperti malam-malam sebelumnya.'] },
      { chapterNumber: 50, title: 'Nasihat Sama Musim Baru', paragraphs: ['Awal musim baru membawa Sari ke bak timbang pengganti untuk meminta arahan Pak Uweng. Lelaki itu masih menyuruhnya bersabar seperti bertahun-tahun sebelumnya. Pak Uweng lalu mengangkat beban pertama musim itu ke bak timbang. Sari membuka buku muatan di mejanya tanpa menulis tanggal pemeriksaan atau menemui lelaki tersebut lagi.'] },
    ], justification: 'A counsel-seeking scene is paraphrased ten times, producing no plan, date, document, or change in their working relationship; the final chapter repeats the first exchange with the bench replaced.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 6, title: 'Gudang Tali Dibuka', paragraphs: ['Gudang tali dibuka kembali sesudah dua musim tertutup dan Sari ditugaskan mendata isinya. Ia menyalin jumlah gulungan dari papan lama tanpa menimbang satu pun. Penjaga gudang berkata bahwa angka papan selalu benar. Sari menyimpan salinan itu di lipatan belakang bukunya dan melanjutkan pekerjaan lain.'] },
      { chapterNumber: 14, title: 'Menimbang Tali Tambat', paragraphs: ['Sari mengangkat gulungan tali tambat yang terasa lebih ringan daripada catatan gudang. Ia bertanya kepada penjaga, tetapi lelaki itu menyebut serat mengering terkena matahari. Sari menulis berat perkiraan di ujung kertas tanpa alat ukur. Pertanyaan pertama berakhir sebagai dugaan yang belum memiliki pembanding.'] },
      { chapterNumber: 15, title: 'Mencari Bekas Potongan', paragraphs: ['Keesokan hari Sari memeriksa ujung tali dan menemukan serat baru dipotong miring. Pak Uweng mengatakan potongan seperti itu biasa dibuat untuk mengikat perahu kecil. Cara pemeriksaannya berubah dari berat ke bentuk, tetapi mereka belum mengetahui siapa yang mengambil tali atau ke mana sisanya dibawa.'] },
      { chapterNumber: 16, title: 'Mengukur Simpul Dermaga', paragraphs: ['Sari mengukur tiga simpul pada perahu kecil dan menemukan satu memakai serat serta potongan miring yang sama. Pemilik perahu mengaku membeli tali di pasar. Ia mencatat nama pasar dan panjang ikatan, memperoleh arah baru tanpa bukti bahwa tali berasal dari gudang.'] },
      { chapterNumber: 32, title: 'Nota Tali Ditemukan', paragraphs: ['Berbulan kemudian pedagang pasar menunjukkan nota penjualan dengan cap gudang pelabuhan, tetapi nama pembeli luntur terkena air. Sari menghubungkan jenis tali, potongan, simpul, dan nota dalam satu berkas. Metodenya terus berubah dan informasi bertambah, namun identitas pengambil tetap belum dapat dipastikan.'] },
      { chapterNumber: 41, title: 'Cap Nota Dibandingkan', paragraphs: ['Sari kembali menemui pedagang pasar sambil membawa salinan nota yang namanya luntur. Lelaki itu mengingat pembeli mengenakan topi anyaman, tetapi tidak dapat menyebut wajah atau suaranya. Sari menggambar bentuk topi pada tepi halaman. Noda air masih menutup seluruh ruang nama pembeli.'] },
      { chapterNumber: 42, title: 'Pedagang Menyebut Rupa', paragraphs: ['Pada kunjungan berikutnya, pedagang itu mengingat topi pembeli memiliki pita gelap di sekeliling tepinya. Sari menambahkan garis hitam pada gambar kecilnya. Ketika ditanya tentang nama, lelaki itu kembali menggeleng. Nota dan gambar tersebut masuk lagi ke map tanpa petunjuk tentang pemilik topi.'] },
      { chapterNumber: 43, title: 'Buku Keluar Diperiksa', paragraphs: ['Sari menunjukkan gambar topi itu kepada pedagang lain di lorong pasar. Perempuan tersebut pernah menjual pita serupa kepada banyak pembeli, namun buku dagangnya tidak memuat identitas mereka. Sari menulis lokasi kios pada halaman yang sama. Menjelang tutup pasar, ia pulang dengan gambar yang bertambah warna namun tetap tanpa pemilik.'] },
      { chapterNumber: 44, title: 'Topi Anyaman Terlihat', paragraphs: ['Hari pasar berikutnya Sari berdiri dekat kios pita dan memperhatikan topi para pengunjung. Tiga lelaki memakai anyaman berpita gelap, lalu masing-masing berbelok ke arah berbeda. Ia tidak mengikuti seorang pun. Tiga garis pendek ditambahkan di bawah gambarnya sebelum map disimpan kembali dalam tas kerja.'] },
      { chapterNumber: 45, title: 'Kantor Sewa Ditanya', paragraphs: ['Sari membawa tiga gambaran lelaki itu kepada pedagang nota. Ia tidak mengenali salah satu sebagai pembeli karena jaraknya terlalu jauh dan musim telah berganti. Sari meminta ciri lain, lalu memperoleh ingatan tentang lengan baju cokelat. Warna tersebut ditulis di bawah gambar topi tanpa menghapus tiga garis kandidat.'] },
      { chapterNumber: 46, title: 'Nota Disinari Lampu', paragraphs: ['Pada sore hujan, Sari kembali meminta pedagang mengingat cara pembeli membawa gulungan tali. Lelaki itu memperagakan satu gulungan di bahu kanan, lalu ragu dan memindahkannya ke kiri. Kedua kemungkinan digambar Sari pada kertas terpisah. Pedagang itu meminta agar jawabannya tidak dianggap pasti.'] },
      { chapterNumber: 47, title: 'Dua Nama Diperiksa', paragraphs: ['Sari memperlihatkan gambar topi kepada Pak Uweng di bak timbang. Juru timbang mengenali model itu sebagai buatan umum dari kampung seberang, dipakai banyak awak kapal. Ia menuliskan nama kampung pada mapnya. Pak Uweng kembali bekerja sebelum Sari sempat menanyakan seorang pemakai tertentu.'] },
      { chapterNumber: 48, title: 'Saksi Menolak Menunjuk', paragraphs: ['Di kampung seberang, pembuat topi mengatakan pita gelap tersedia pada hampir setiap rumah penganyam. Ia menunjukkan empat contoh yang bentuknya serupa. Sari menyalin nama kampung dan jumlah penganyam, lalu menyimpan kembali gambar lama. Tidak ada daftar pembeli yang dapat dibawa pulang dari tempat itu.'] },
      { chapterNumber: 49, title: 'Berkas Tali Diserahkan', paragraphs: ['Sari menyusun nota, gambar topi, dan catatan kampung di atas meja kamar. Semua ciri dapat dibaca, tetapi tidak satu pun mengarah kepada nama tertentu. Ia mengikat map itu dengan tali baru dan memasukkannya ke tas. Esoknya tas tersebut tetap berada di bawah meja kerja sepanjang hari.'] },
      { chapterNumber: 50, title: 'Gudang Tali Ditimbang', paragraphs: ['Musim berikutnya membawa Sari kembali ke kios pedagang bersama map yang sama. Lelaki itu membaca catatannya lalu mengulang ciri topi berpita dan lengan cokelat. Sari menambahkan tanggal kunjungan baru pada halaman belakang. Ruang nama pembeli di nota masih tertutup noda air ketika map ditutup.'] },
    ], justification: 'Each chapter changes method and adds bounded information about missing mooring rope, while the washed buyer name prevents a complete conclusion and avoids the odd-ticket spine; the runway keeps narrowing candidates without ever producing an admission.' },
    { chapters: [
      { chapterNumber: 6, title: 'Membeli Buku Kecil', paragraphs: ['Sari membeli buku kecil bersampul kain di kios depan gerbang pelabuhan pada pekan pertama ia bekerja. Penjualnya menyarankan sampul kain karena tahan lembap. Ia menuliskan tanggal pembelian di halaman awal lalu memasukkannya ke saku baju. Buku tersebut belum berisi apa pun selain tanggal itu.'] },
      { chapterNumber: 14, title: 'Menaruh Buku Kolong', paragraphs: ['Sari menyelipkan buku kecil ke kolong lantai kamar seperti malam-malam sebelumnya dan menutupnya dengan tikar. Ia memeriksa daun pintu dua kali. Kebiasaan tersebut memberinya rasa aman tanpa sedikit pun mengubah letak persoalan garam itu. Tidak ada halaman baru yang bertambah pada malam itu.'] },
      { chapterNumber: 15, title: 'Menaruh Buku Lagi', paragraphs: ['Ritual yang sama diulang, kali ini setelah menuliskan satu baris berat karung. Tikar dikembalikan pada posisi yang sama dan daun pintu kamar diperiksa dua kali seperti biasa. Satu baris angka tersebut merupakan tambahan kecil, sedangkan bentuk malamnya sama sekali tidak berbeda dengan malam sebelumnya.'] },
      { chapterNumber: 16, title: 'Menaruh Buku Lembap', paragraphs: ['Lantai kamar lembap oleh hujan dan Sari tetap menyelipkan buku ke kolong yang sama. Ia menambahkan sehelai plastik pembungkus sebelum menutup tikar. Persoalannya masih tersembunyi pada kolong yang serupa dengan dua malam sebelumnya, tetapi kini catatan tersebut sanggup bertahan lebih lama daripada musim hujan.'] },
      { chapterNumber: 32, title: 'Menaruh Buku Tebal', paragraphs: ['Buku tersebut kini lebih tebal, dan kolong lantai nyaris tidak muat. Sari tetap melakukan gerakan yang sama sambil memeriksa pintu dua kali. Ketebalan itu memaksanya mulai memikirkan tempat penyimpanan lain di luar kamar, satu-satunya perubahan yang lahir dari kebiasaan berulang tersebut.'] },
      { chapterNumber: 41, title: 'Menaruh Buku Terbelah', paragraphs: ['Sari membelah isi bukunya menjadi dua bagian dan menyelipkan keduanya ke kolong lantai yang sama. Ia meratakan tikar dari sisi ranjang menuju dinding depan, lalu menekan gagang pintu dua kali. Dua bundel itu masuk melalui papan yang biasa diangkat dan berhenti berdampingan di atas tanah lembap.'] },
      { chapterNumber: 42, title: 'Menaruh Buku Terbungkus', paragraphs: ['Malam berikutnya kedua bagian itu ia bungkus kain sebelum diselipkan ke kolong yang sama. Sari mengangkat tikar, menurunkan bundel melalui papan, lalu memeriksa pintu dua kali. Bungkus kain tersebut membuat bunyi gesekan hilang. Sesudah bunyi lenyap, ia meratakan tikar dan menekan tepinya dengan telapak tangan.'] },
      { chapterNumber: 43, title: 'Menaruh Buku Bergegas', paragraphs: ['Sari pulang terlambat dan menjalankan ritual itu dengan tergesa, melewatkan pemeriksaan pintu yang kedua. Ia terbangun tengah malam untuk memeriksanya. Ritualnya kembali utuh sebelum subuh. Sejak malam itu ia memasang telapak pada daun pintu sekali lagi sebelum berbaring, sesudah lampu kamar dipadamkan.'] },
      { chapterNumber: 44, title: 'Menaruh Buku Bersuara', paragraphs: ['Papan kolong berderit lebih keras daripada biasanya dan Sari menahannya dengan telapak tangan. Ia mengganjal papan tersebut memakai potongan karet sandal. Potongan karet menahan papan hingga tidak berderit ketika tikar diratakan kembali. Potongan karet tersebut berasal dari sandal adiknya yang putus.'] },
      { chapterNumber: 45, title: 'Menaruh Buku Kemarau', paragraphs: ['Kemarau membuat lantai retak halus dan kolong terlihat dari sudut tertentu. Sari mengangkat tikar, memasukkan buku melalui papan yang biasa, lalu menggeser penutup lantai sedikit lebih lebar. Tepi tikar kini mencapai kaki ranjang dan menutup keempat garis retak tersebut. Setelah memeriksa pintu dua kali, ia menghitung empat garis pendek itu dari sisi ranjang.'] },
      { chapterNumber: 46, title: 'Menaruh Buku Tamu', paragraphs: ['Latif membawa temannya menginap dan Sari menunggu keduanya tidur sebelum menjalankan ritual yang sama. Ia menunda satu jam tanpa mengubah urutan gerakannya. Buku itu tetap masuk ke kolong yang sama. Jam dinding berbunyi sekali sebelum ia berani mengangkat tikar di depan para tamu. Napas kedua tamu itu terdengar berat dari balik dinding papan.'] },
      { chapterNumber: 47, title: 'Menaruh Buku Berdua', paragraphs: ['Latif memergokinya dan Sari hanya berkata bahwa itu buku kerja. Adiknya tidak bertanya lebih jauh lalu kembali tidur. Ritual malam itu diselesaikan seperti biasa dengan pintu diperiksa dua kali. Latif kini mengetahui letak kolong tersebut dan memandang tikar itu sebelum kembali tidur.'] },
      { chapterNumber: 48, title: 'Menaruh Buku Penuh', paragraphs: ['Kedua bagian buku sudah penuh dan Sari menyelipkan lembar lepas di antaranya. Kolong lantai menerimanya dengan susah payah. Gerakan menutup tikar dan memeriksa pintu tetap sama. Lembar lepas tersebut membuatnya mulai menimbang lemari gudang sebagai tempat berikutnya. Isinya berupa salinan nomor surat jalan bulan lalu.'] },
      { chapterNumber: 49, title: 'Menaruh Buku Terakhir', paragraphs: ['Malam sebelum musim berganti, Sari menjalankan ritual itu dan berhenti lebih lama sambil memandangi tikar. Ia tidak memindahkan apa pun. Daun pintu diperiksanya dua kali menurut kebiasaan. Persoalan garam masih tersembunyi pada lokasi awal dan belum berpindah keluar kamar hingga musim berganti.'] },
      { chapterNumber: 50, title: 'Menaruh Buku Baru', paragraphs: ['Pada malam pembuka musim berikutnya, Sari menyelipkan buku bersampul kain baru di bawah papan kamar. Tikar dikembalikan, pintu diperiksa dua kali. Sampul baru yang masih bersih masuk ke ruang tanah yang sudah dipenuhi dua bundel bernoda garam. Sari meratakan tikar dan memeriksa pintu dua kali.'] },
    ], justification: 'A deliberately repeated hiding ritual gains only one incremental consequence per chapter without changing the underlying situation, and the runway closes on the same gesture it opened with.' },
    { chapters: [
      { chapterNumber: 6, title: 'Jalan Pulang Dipilih', paragraphs: ['Sari memilih jalan pulang menyusuri pagar batu karena lebih cepat sampai ke kamar sewaannya. Jalan tersebut melewati beberapa rumah pegawai kantor izin. Ia belum mengenal siapa pun yang tinggal di sana. Pilihan jalan itu ia buat sekali dan tidak pernah ia tinjau ulang.'] },
      { chapterNumber: 14, title: 'Melewati Rumah Damar', paragraphs: ['Sari melewati rumah Regent Damar dalam perjalanan pulang dan memperlambat langkah tanpa berhenti. Lampu serambi menyala dan terdengar suara orang berbicara. Ia memilih meneruskan jalan pulang menyusuri pagar. Tidak ada nama yang ia kenali dari suara tersebut dan tidak sepatah pun ia catat malam itu.'] },
      { chapterNumber: 15, title: 'Melewati Sambil Berhenti', paragraphs: ['Malam berikutnya ia melewati rumah tersebut dan berhenti sejenak di bawah pohon ketapang. Suara yang sama terdengar lagi dari serambi, kali ini menyebut kata jadwal pasang dengan jelas. Sari meneruskan langkahnya setelah menahan napas beberapa saat. Kata tersebut ia simpan di kepala tanpa menuliskannya di mana pun.'] },
      { chapterNumber: 16, title: 'Melewati Bawa Kertas', paragraphs: ['Kali ini Sari membawa kertas dan menuliskan kata jadwal pasang setelah menjauh beberapa langkah. Bentuk kejadiannya nyaris sama seperti dua malam terdahulu: berjalan menyusuri pagar, memperlambat langkah, mendengar sepotong kalimat, lalu meneruskan pulang. Tambahannya hanya satu, yaitu kata tersebut sekarang tersimpan di luar ingatannya sendiri.'] },
      { chapterNumber: 32, title: 'Melewati Rumah Sepi', paragraphs: ['Rumah itu sepi ketika Sari melewatinya pada musim berikutnya. Ia tetap memperlambat langkah karena kebiasaan. Kertas lipat di sakunya sudah memuat tiga potong kata dari tiga malam berbeda, dan itulah satu-satunya hasil dari perjalanan pulang yang selalu mengambil bentuk sama.'] },
      { chapterNumber: 41, title: 'Melewati Dengar Angka', paragraphs: ['Sari melewati pagar itu lagi dan memperlambat langkah seperti biasa. Dari serambi terdengar sebuah angka disebut dua kali, tanpa satuan maupun nama. Ia menuliskannya setelah menjauh beberapa langkah. Angka itu menjadi potongan keempat pada kertas lipatnya. Anjing tetangga menyalak sekali ketika ia melewati tikungan.'] },
      { chapterNumber: 42, title: 'Melewati Hujan Rintik', paragraphs: ['Hujan rintik membuat suara serambi lebih pelan ketika Sari melewatinya. Ia hanya menangkap kata gudang tanpa kelanjutan kalimatnya. Kata tersebut ia tambahkan pada kertas lipat di sakunya. Langkahnya tetap melambat lalu berlanjut seperti pada malam mana pun. Air menetes dari genting serambi ke batu halaman.'] },
      { chapterNumber: 43, title: 'Melewati Pagar Baru', paragraphs: ['Pagar rumah tersebut diganti dengan tembok lebih tinggi, dan Sari tetap melewatinya dengan langkah melambat. Suara dari serambi kini nyaris tidak terdengar. Ia hanya menangkap satu tawa panjang. Kertas lipatnya tidak bertambah selain catatan bahwa tembok telah ditinggikan. Cat tembok baru tersebut masih berbau ketika ia lewat.'] },
      { chapterNumber: 44, title: 'Melewati Bawa Payung', paragraphs: ['Sari membawa payung dan berhenti lebih lama dengan alasan menutupnya di depan tembok. Ia menangkap sepotong kata mengenai jadwal kapal. Potongan itu ditulis begitu ia sampai di simpang. Payung ditutup di simpang setelah potongan kata tersebut selesai ditulis pada kertas lipatnya.'] },
      { chapterNumber: 45, title: 'Melewati Ada Tamu', paragraphs: ['Beberapa sepatu berjajar di depan pintu rumah tersebut ketika Sari melewatinya. Ia menghitung jumlahnya sambil berjalan pelan. Jumlah sepatu tersebut ditulis sebagai potongan baru pada kertas sakunya. Sepatu paling ujung berwarna cokelat tua dan ukurannya jauh lebih besar. Pintu rumah tersebut tidak terbuka sekali pun sampai ia menjauh. Pada kertas lipatnya malam itu hanya tertulis jumlah sepatu yang berjajar.'] },
      { chapterNumber: 46, title: 'Melewati Dijaga Orang', paragraphs: ['Seorang lelaki duduk di depan tembok dan memperhatikan siapa pun yang lewat. Sari berjalan dengan kecepatan biasa dan tidak melambat malam itu. Ia tidak mendengar apa pun dari serambi. Kertas lipatnya tetap sama, dan ia mencatat bahwa penjagaan tersebut telah dimulai.'] },
      { chapterNumber: 47, title: 'Melewati Jalan Memutar', paragraphs: ['Sari memutar lewat jalan belakang selama beberapa malam lalu kembali ke jalan lamanya. Ia melambat lagi di depan tembok. Tidak ada suara dari serambi karena rumah gelap. Kertas lipatnya tidak menerima tambahan malam itu. Jalan belakang telah memakan waktu sepuluh menit lebih lama.'] },
      { chapterNumber: 48, title: 'Melewati Bawa Latif', paragraphs: ['Latif menemaninya pulang dan Sari tetap melambat di depan tembok. Adiknya bertanya mengapa langkahnya berubah dan Sari menjawab kakinya pegal. Tidak ada suara yang terdengar malam itu. Latif menerima alasan tentang kaki pegal, lalu berjalan di sampingnya tanpa bertanya lagi sampai rumah.'] },
      { chapterNumber: 49, title: 'Melewati Kertas Penuh', paragraphs: ['Kertas lipat di saku Sari sudah memuat tujuh potong kata dari tujuh malam berbeda. Ia membacanya dekat cahaya menara, tetapi potongan tersebut belum membentuk kalimat. Kertas itu ia lipat kembali. Perjalanan pulang esok hari ia rencanakan menempuh jalan yang sama.'] },
      { chapterNumber: 50, title: 'Melewati Rumah Kosong', paragraphs: ['Rumah tersebut kosong pada musim berikutnya dan papan sewa dipasang di temboknya. Sari tetap melambat ketika melewatinya. Kertas lipat itu masih berada di sakunya dengan tujuh potong kata yang belum membentuk kalimat. Ia melewati papan sewa, memperlambat langkah, lalu pulang.'] },
    ], justification: 'The walk past the antagonist house repeats with the same shape while each pass yields one modest overheard fragment, and the runway ends with the fragments still unjoined.' },
  ],
}
